//! The `review_revision` table: the edit history of a [`review`](super::review). One
//! row per edit a reviewer makes to their review, preserving the prior version's
//! change as an autogenerated diff plus the reviewer's note explaining it. A review's
//! revisions are ordered by [`edited_at`](Model::edited_at); replaying their diffs
//! from the original walks the review forward to its current content.

use sea_orm::entity::prelude::*;

#[derive(Clone, Debug, PartialEq, Eq, DeriveEntityModel)]
#[sea_orm(table_name = "review_revision")]
pub struct Model {
    /// The revision's own id (a UUID); the primary key.
    #[sea_orm(primary_key, auto_increment = false)]
    pub id: String,
    /// The review this revision belongs to (FK to `review.id`). Indexed and
    /// non-unique — a review accrues one revision per edit.
    pub review_id: String,
    /// RFC 3339 of when this edit was made. The newest revision's timestamp is also
    /// mirrored onto `review.edited_at`.
    pub edited_at: String,
    /// The reviewer's note explaining what changed and why (required on every edit).
    #[sea_orm(column_type = "Text")]
    pub note: String,
    /// The autogenerated diff from the content before this edit to the content after,
    /// as a JSON `ReviewDiff`.
    #[sea_orm(column_type = "Text")]
    pub diff: String,
}

#[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
pub enum Relation {
    #[sea_orm(
        belongs_to = "super::review::Entity",
        from = "Column::ReviewId",
        to = "super::review::Column::Id",
        on_delete = "Cascade"
    )]
    Review,
}

impl Related<super::review::Entity> for Entity {
    fn to() -> RelationDef {
        Relation::Review.def()
    }
}

impl ActiveModelBehavior for ActiveModel {}
